solution:
#include <iostream>

int main() {
    int objectif, versement;
    std::cin >> objectif >> versement;
    int epargne = 0;
    int semaines = 0;
    while (epargne < objectif) {
        epargne += versement;
        semaines++;
    }
    std::cout << "Semaines : " << semaines << "\n";
    std::cout << "Épargne : " << epargne << " FCFA\n";
    return 0;
}
